INSERT INTO store (id, name, code, address, city, state, active) SELECT id, name, code, address, city, state, active FROM expected_store
INSERT INTO category (id, code, name, active) SELECT id, code, name, active FROM expected_category
INSERT INTO product (id, category_id, sku, name, description, active) SELECT id, category_id, sku, name, description, active FROM expected_product
INSERT INTO store_product (id, store_id, product_id, active) SELECT id, store_id, product_id, active FROM expected_store_product
INSERT INTO store_map (id, store_id, version, name, width, height, scale_meters_per_unit, status) SELECT id, store_id, version, name, width, height, scale_meters_per_unit, status FROM expected_store_map
INSERT INTO sector (id, map_id, code, name, x, y, width, height, rotation, active) SELECT id, map_id, code, name, x, y, width, height, rotation, active FROM expected_sector
INSERT INTO aisle (id, map_id, code, name, x, y, width, height, rotation, active, sector_id) SELECT id, map_id, code, name, x, y, width, height, rotation, active, sector_id FROM expected_aisle
INSERT INTO shelf_block (id, map_id, code, name, x, y, width, height, rotation, active, sector_id, aisle_id) SELECT id, map_id, code, name, x, y, width, height, rotation, active, sector_id, aisle_id FROM expected_shelf_block
INSERT INTO map_node (id, map_id, type, x, y, label, active) SELECT id, map_id, type, x, y, label, active FROM expected_map_node
INSERT INTO map_edge (id, map_id, from_node_id, to_node_id, distance_meters, bidirectional, active) SELECT id, map_id, from_node_id, to_node_id, distance_meters, bidirectional, active FROM expected_map_edge
INSERT INTO point_of_interest (id, map_id, navigation_node_id, type, name, x, y, active) SELECT id, map_id, navigation_node_id, type, name, x, y, active FROM expected_point_of_interest
INSERT INTO product_location (id, store_id, store_product_id, map_id, sector_id, aisle_id, shelf_block_id, module, shelf_level, x, y, navigation_node_id, primary_location, active) SELECT id, store_id, store_product_id, map_id, sector_id, aisle_id, shelf_block_id, module, shelf_level, x, y, navigation_node_id, primary_location, active FROM expected_product_location
